import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_02_01_first_task.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_02_02_app.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_02_03_cli.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_02_04_ide.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_02_05_cloud.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_02_06_agents.png",q=JSON.parse('{"title":"四个入口怎么选：Codex App、CLI、IDE 与 Cloud 官方上手指南","description":"新手最容易把时间浪费在“到底装哪个 Codex”上。官方文档给出的答案并不是四选一，而是先区分运行位置和工作方式：本地入口共享当前工作区，Cloud 在托管环境中执行；桌面端强调任务编排与审阅，CLI 强调终端控制，IDE 强调编辑器上下文。","frontmatter":{"title":"四个入口怎么选：Codex App、CLI、IDE 与 Cloud 官方上手指南","description":"新手最容易把时间浪费在“到底装哪个 Codex”上。官方文档给出的答案并不是四选一，而是先区分运行位置和工作方式：本地入口共享当前工作区，Cloud 在托管环境中执行；桌面端强调任务编排与审阅，CLI 强调终端控制，IDE 强调编辑器上下文。","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":5,"source":"2026-08-10/ai_codex_official_02_surfaces_quickstart.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_02_01_first_task.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"四个入口怎么选：Codex App、CLI、IDE 与 Cloud 官方上手指南"}],["meta",{"property":"og:description","content":"新手最容易把时间浪费在“到底装哪个 Codex”上。官方文档给出的答案并不是四选一，而是先区分运行位置和工作方式：本地入口共享当前工作区，Cloud 在托管环境中执行；桌面端强调任务编排与审阅，CLI 强调终端控制，IDE 强调编辑器上下文。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_02_01_first_task.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"四个入口怎么选：Codex App、CLI、IDE 与 Cloud 官方上手指南"}],["meta",{"name":"twitter:description","content":"新手最容易把时间浪费在“到底装哪个 Codex”上。官方文档给出的答案并不是四选一，而是先区分运行位置和工作方式：本地入口共享当前工作区，Cloud 在托管环境中执行；桌面端强调任务编排与审阅，CLI 强调终端控制，IDE 强调编辑器上下文。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_02_01_first_task.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-02-surfaces-quickstart.md","filePath":"archive/ai-codex-official-02-surfaces-quickstart.md","lastUpdated":null}'),h={name:"archive/ai-codex-official-02-surfaces-quickstart.md"};function p(_,a,u,f,m,x){return t(),i("div",null,[...a[0]||(a[0]=[o('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="四个入口怎么选-codex-app、cli、ide-与-cloud-官方上手指南" tabindex="-1">四个入口怎么选：Codex App、CLI、IDE 与 Cloud 官方上手指南 <a class="header-anchor" href="#四个入口怎么选-codex-app、cli、ide-与-cloud-官方上手指南" aria-label="Permalink to &quot;四个入口怎么选：Codex App、CLI、IDE 与 Cloud 官方上手指南&quot;">​</a></h1><p>新手最容易把时间浪费在“到底装哪个 Codex”上。官方文档给出的答案并不是四选一，而是先区分运行位置和工作方式：本地入口共享当前工作区，Cloud 在托管环境中执行；桌面端强调任务编排与审阅，CLI 强调终端控制，IDE 强调编辑器上下文。</p><h2 id="一、开始前先准备可恢复项目" tabindex="-1">一、开始前先准备可恢复项目 <a class="header-anchor" href="#一、开始前先准备可恢复项目" aria-label="Permalink to &quot;一、开始前先准备可恢复项目&quot;">​</a></h2><h3 id="_1-1-使用版本控制仓库" tabindex="-1">1.1 使用版本控制仓库 <a class="header-anchor" href="#_1-1-使用版本控制仓库" aria-label="Permalink to &quot;1.1 使用版本控制仓库&quot;">​</a></h3><p>Git 能让代理修改变成可观察 Diff，也让已有用户改动得到保护。第一次练习应选择可以丢弃的小仓库，不在生产仓库中测试未知权限与自动化行为。</p><h3 id="_1-2-确认工作目录与当前状态" tabindex="-1">1.2 确认工作目录与当前状态 <a class="header-anchor" href="#_1-2-确认工作目录与当前状态" aria-label="Permalink to &quot;1.2 确认工作目录与当前状态&quot;">​</a></h3><p>Codex 读取的是当前执行环境中的文件。启动前检查目录、分支、未提交修改和项目规则，避免代理在错误仓库中完成一个“看似正确”的任务。</p><h3 id="_1-3-把完成条件写进任务" tabindex="-1">1.3 把完成条件写进任务 <a class="header-anchor" href="#_1-3-把完成条件写进任务" aria-label="Permalink to &quot;1.3 把完成条件写进任务&quot;">​</a></h3><p>“帮我看看项目”没有明确终点。“解释入口、修改指定函数、运行某项测试并报告 Diff”才是一条可以验收的任务链。</p><p><img src="'+r+'" alt="图 1：第一次任务从仓库检查到 Diff 与验证"></p><h2 id="二、桌面端适合可视化任务编排" tabindex="-1">二、桌面端适合可视化任务编排 <a class="header-anchor" href="#二、桌面端适合可视化任务编排" aria-label="Permalink to &quot;二、桌面端适合可视化任务编排&quot;">​</a></h2><h3 id="_2-1-thread-是任务边界" tabindex="-1">2.1 Thread 是任务边界 <a class="header-anchor" href="#_2-1-thread-是任务边界" aria-label="Permalink to &quot;2.1 Thread 是任务边界&quot;">​</a></h3><p>一个 Thread 应围绕一个主目标，保留相关上下文、工具过程和反馈。将多个无关问题塞进同一线程，会让范围、权限和结束条件彼此污染。</p><h3 id="_2-2-local-与-worktree-提供不同隔离" tabindex="-1">2.2 Local 与 Worktree 提供不同隔离 <a class="header-anchor" href="#_2-2-local-与-worktree-提供不同隔离" aria-label="Permalink to &quot;2.2 Local 与 Worktree 提供不同隔离&quot;">​</a></h3><p>Local 直接使用当前工作区，适合继续开发者手上的任务；Worktree 为并行任务提供独立检出，减少两个任务互相读取未完成改动。隔离工作树并不自动解决公共接口冲突，最终仍需 Review。</p><h3 id="_2-3-diff-面板是验收入口" tabindex="-1">2.3 Diff 面板是验收入口 <a class="header-anchor" href="#_2-3-diff-面板是验收入口" aria-label="Permalink to &quot;2.3 Diff 面板是验收入口&quot;">​</a></h3><p>图形化 Review 能把代理解释与实际改动放在一起。用户对具体行的反馈会成为下一轮上下文，比一句“还是不对”更有信息量。</p><p><img src="'+l+'" alt="图 2：桌面端通过 Thread、Worktree 与 Diff 管理任务"></p><h2 id="三、cli-适合终端工作流" tabindex="-1">三、CLI 适合终端工作流 <a class="header-anchor" href="#三、cli-适合终端工作流" aria-label="Permalink to &quot;三、CLI 适合终端工作流&quot;">​</a></h2><h3 id="_3-1-交互模式适合边观察边纠偏" tabindex="-1">3.1 交互模式适合边观察边纠偏 <a class="header-anchor" href="#_3-1-交互模式适合边观察边纠偏" aria-label="Permalink to &quot;3.1 交互模式适合边观察边纠偏&quot;">​</a></h3><p>在仓库中启动 <code>codex</code> 后，可以用自然语言描述任务、查看状态、调整权限并继续对话。它适合调试、搜索、构建和测试密集的项目。</p><h3 id="_3-2-斜杠命令管理会话而不是业务目标" tabindex="-1">3.2 斜杠命令管理会话而不是业务目标 <a class="header-anchor" href="#_3-2-斜杠命令管理会话而不是业务目标" aria-label="Permalink to &quot;3.2 斜杠命令管理会话而不是业务目标&quot;">​</a></h3><p>模型、权限、状态、Review 和压缩属于控制面；业务目标仍应写成自然语言。不要把项目约束寄托在某个短命令上。</p><h3 id="_3-3-非交互执行属于自动化章节" tabindex="-1">3.3 非交互执行属于自动化章节 <a class="header-anchor" href="#_3-3-非交互执行属于自动化章节" aria-label="Permalink to &quot;3.3 非交互执行属于自动化章节&quot;">​</a></h3><p><code>codex exec</code> 面向脚本与 CI，不是交互会话的简单别名。它需要确定输入、结构化输出、退出状态与预设权限，本系列第八篇单独展开。</p><p><img src="'+c+'" alt="图 3：交互式 CLI 与非交互执行的职责分工"></p><h2 id="四、ide-入口用精确上下文降低噪声" tabindex="-1">四、IDE 入口用精确上下文降低噪声 <a class="header-anchor" href="#四、ide-入口用精确上下文降低噪声" aria-label="Permalink to &quot;四、IDE 入口用精确上下文降低噪声&quot;">​</a></h2><h3 id="_4-1-当前文件与选区提供定位" tabindex="-1">4.1 当前文件与选区提供定位 <a class="header-anchor" href="#_4-1-当前文件与选区提供定位" aria-label="Permalink to &quot;4.1 当前文件与选区提供定位&quot;">​</a></h3><p>编辑器知道正在查看的文件和选中代码，适合局部实现、解释和即时 Review。精确上下文减少无关搜索，却不意味着代理只会读取选区。</p><h3 id="_4-2-ide-与-cli-应共享项目规则" tabindex="-1">4.2 IDE 与 CLI 应共享项目规则 <a class="header-anchor" href="#_4-2-ide-与-cli-应共享项目规则" aria-label="Permalink to &quot;4.2 IDE 与 CLI 应共享项目规则&quot;">​</a></h3><p>同一仓库的构建、测试和代码风格不应为不同入口复制多份。<code>AGENTS.md</code> 与项目配置承担跨入口事实，临时要求保留在当前 Prompt。</p><h3 id="_4-3-复杂长任务可以转向其他执行域" tabindex="-1">4.3 复杂长任务可以转向其他执行域 <a class="header-anchor" href="#_4-3-复杂长任务可以转向其他执行域" aria-label="Permalink to &quot;4.3 复杂长任务可以转向其他执行域&quot;">​</a></h3><p>当任务需要大量构建、并行探索或长时间运行时，可以在 Worktree、CLI 或 Cloud 中执行，再回到 IDE 审查局部结果。</p><p><img src="'+d+'" alt="图 4：IDE 通过文件、选区与调用位置压缩上下文"></p><h2 id="五、cloud-必须从仓库重建现实" tabindex="-1">五、Cloud 必须从仓库重建现实 <a class="header-anchor" href="#五、cloud-必须从仓库重建现实" aria-label="Permalink to &quot;五、Cloud 必须从仓库重建现实&quot;">​</a></h2><h3 id="_5-1-environment-定义依赖和工具" tabindex="-1">5.1 Environment 定义依赖和工具 <a class="header-anchor" href="#_5-1-environment-定义依赖和工具" aria-label="Permalink to &quot;5.1 Environment 定义依赖和工具&quot;">​</a></h3><p>Cloud 任务看不到本机隐藏状态，需要从仓库、设置脚本和环境配置建立可运行现场。能够在干净环境重建，是云端可靠性的前提。</p><h3 id="_5-2-设置阶段与代理阶段应分离" tabindex="-1">5.2 设置阶段与代理阶段应分离 <a class="header-anchor" href="#_5-2-设置阶段与代理阶段应分离" aria-label="Permalink to &quot;5.2 设置阶段与代理阶段应分离&quot;">​</a></h3><p>官方安全模型允许设置阶段安装依赖并使用必要 Secrets，代理阶段默认更受限制。秘密不应作为长期上下文留给模型，也不应写进仓库。</p><h3 id="_5-3-远程结果仍要进入-git-审查链" tabindex="-1">5.3 远程结果仍要进入 Git 审查链 <a class="header-anchor" href="#_5-3-远程结果仍要进入-git-审查链" aria-label="Permalink to &quot;5.3 远程结果仍要进入 Git 审查链&quot;">​</a></h3><p>Cloud 可以产出 Diff 或 Pull Request，但合并前仍需测试、Review 和仓库保护规则。远程完成不等于自动发布。</p><p><img src="'+n+'" alt="图 5：Cloud 从仓库、环境脚本与受控秘密重建任务"></p><h2 id="六、身份认证决定入口-不决定全部权限" tabindex="-1">六、身份认证决定入口，不决定全部权限 <a class="header-anchor" href="#六、身份认证决定入口-不决定全部权限" aria-label="Permalink to &quot;六、身份认证决定入口，不决定全部权限&quot;">​</a></h2><p>ChatGPT 登录、API Key、GitHub 连接和第三方系统授权属于不同边界。登录 Codex 不等于拥有仓库写入权限，连接 GitHub 也不等于本地命令能够访问网络。凭据应使用官方登录流程和安全存储，不进入 Prompt、源码或日志。</p><h2 id="七、agents-md-让入口共享项目契约" tabindex="-1">七、AGENTS.md 让入口共享项目契约 <a class="header-anchor" href="#七、agents-md-让入口共享项目契约" aria-label="Permalink to &quot;七、AGENTS.md 让入口共享项目契约&quot;">​</a></h2><h3 id="_7-1-写行动规则而不是百科全书" tabindex="-1">7.1 写行动规则而不是百科全书 <a class="header-anchor" href="#_7-1-写行动规则而不是百科全书" aria-label="Permalink to &quot;7.1 写行动规则而不是百科全书&quot;">​</a></h3><p>有效内容包括仓库结构、构建测试命令、代码规范、禁止动作和完成标准。模糊口号会占用上下文，却不能指导具体行动。</p><h3 id="_7-2-更近的规则描述局部差异" tabindex="-1">7.2 更近的规则描述局部差异 <a class="header-anchor" href="#_7-2-更近的规则描述局部差异" aria-label="Permalink to &quot;7.2 更近的规则描述局部差异&quot;">​</a></h3><p>全局规则提供个人默认，仓库规则提供团队标准，子目录文件补充局部约束。代理应读取目标路径适用的规则链。</p><h3 id="_7-3-规则必须保持真实" tabindex="-1">7.3 规则必须保持真实 <a class="header-anchor" href="#_7-3-规则必须保持真实" aria-label="Permalink to &quot;7.3 规则必须保持真实&quot;">​</a></h3><p>过时命令比没有命令更危险。团队应在构建方式、目录结构或发布流程变化后更新规则，并把临时任务要求留在 Prompt 中。</p><p><img src="'+s+'" alt="图 6：全局、仓库、目录与当前任务规则逐层生效"></p><h2 id="八、官方参考资料" tabindex="-1">八、官方参考资料 <a class="header-anchor" href="#八、官方参考资料" aria-label="Permalink to &quot;八、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/quickstart" target="_blank" rel="noreferrer">OpenAI Docs：Quickstart</a></p><p><a href="https://learn.chatgpt.com/docs/codex/cli" target="_blank" rel="noreferrer">OpenAI Docs：Codex CLI</a></p><p><a href="https://learn.chatgpt.com/docs/cloud" target="_blank" rel="noreferrer">OpenAI Docs：Codex Cloud</a></p><p><a href="https://learn.chatgpt.com/docs/agent-configuration/agents-md" target="_blank" rel="noreferrer">OpenAI Docs：AGENTS.md</a></p>',58)])])}const C=e(h,[["render",p]]);export{q as __pageData,C as default};
